package payout

// BattleRoyale is the winner-takes-all rule. The pot is every stake; the fee is
// taken from it, and the rest goes to:
//
//   - the last player in;
//   - when the clock ran out with several in, the one of them with the most
//     kills, and players still in with as many kills share it equally;
//   - and when everyone is out, the player who went out last.
//
// It is won by staying in the air, not by scoring: the kill target is
// ignored, and the arena realm refuses a battle-royale spec that has one.
//
// What the split leaves over goes to the fee.
type BattleRoyale struct{}

var _ Rule = BattleRoyale{}

func (BattleRoyale) Mode() string { return ModeBattleRoyale }

func (BattleRoyale) Settle(g Game, players []address, deaths []Death) (Result, error) {
	t, err := check(g, players, deaths)
	if err != nil {
		return Result{}, err
	}
	// The most kills among the players still in.
	best := int64(-1)
	for i := range players {
		if !t.out(i, g.Lives) && t.kills[i] > best {
			best = t.kills[i]
		}
	}
	won := make([]bool, len(players))
	winners := int64(0)
	for i := range players {
		if !t.out(i, g.Lives) && t.kills[i] == best {
			won[i] = true
			winners++
		}
	}
	if winners == 0 {
		won[t.lastOut] = true
		winners = 1
	}

	pot := g.Stake * int64(len(players))
	share := afterFee(pot, g.FeeBps) / winners
	res := Result{Fee: pot - share*winners}
	if share == 0 {
		return res, nil // a pot too small to split: nobody is paid
	}
	for i, p := range players {
		if won[i] {
			res.Payouts = append(res.Payouts, Payout{Address: p, Amount: share})
		}
	}
	return res, nil
}

package payout

// rankWeights are the shares of the top three by kills, in basis points.
var rankWeights = [3]int64{6000, 3000, 1000}

// Deathmatch pays the most kills. The pot is every stake; the fee is taken from
// it, and the rest goes to the top three by kills: 60%, 30% and 10%.
//
//   - Only players with at least one kill are ranked. With fewer than three
//     of them, the shares of the ranks they fill are rescaled to the whole:
//     one killer takes everything, two take 2/3 and 1/3.
//   - Players with as many kills share the ranks they hold: two tied first
//     split 60% + 30%, and the next one is third.
//   - When nobody killed anybody, every player gets their stake back and the
//     house takes nothing.
//
// Deaths cost nothing here beyond the lives they take. What rounding leaves
// over goes to the fee.
type Deathmatch struct{}

var _ Rule = Deathmatch{}

func (Deathmatch) Mode() string { return ModeDeathmatch }

func (Deathmatch) Settle(g Game, players []address, deaths []Death) (Result, error) {
	t, err := check(g, players, deaths)
	if err != nil {
		return Result{}, err
	}
	pot := g.Stake * int64(len(players))

	// Killers, most kills first; equal kills keep the order of the players.
	var ranked []int
	for i := range players {
		if t.kills[i] == 0 {
			continue
		}
		at := len(ranked)
		for at > 0 && t.kills[ranked[at-1]] < t.kills[i] {
			at--
		}
		ranked = append(ranked, 0)
		copy(ranked[at+1:], ranked[at:])
		ranked[at] = i
	}
	if len(ranked) == 0 {
		res := Result{}
		for _, p := range players {
			res.Payouts = append(res.Payouts, Payout{Address: p, Amount: g.Stake})
		}
		return res, nil
	}

	filled := len(ranked)
	if filled > len(rankWeights) {
		filled = len(rankWeights)
	}
	whole := int64(0)
	for _, w := range rankWeights[:filled] {
		whole += w
	}

	prize := afterFee(pot, g.FeeBps)
	amounts := make([]int64, len(players))
	for pos := 0; pos < filled; {
		end := pos + 1
		for end < len(ranked) && t.kills[ranked[end]] == t.kills[ranked[pos]] {
			end++
		}
		weight := int64(0)
		for r := pos; r < end && r < filled; r++ {
			weight += rankWeights[r]
		}
		group := int64(end - pos)
		// prize <= 8e12 and weight <= 1e4: the product stays far below 2^63.
		each := prize * weight / (whole * group)
		for _, i := range ranked[pos:end] {
			amounts[i] = each
		}
		pos = end
	}

	res := Result{Fee: pot}
	for i, p := range players {
		if amounts[i] > 0 {
			res.Payouts = append(res.Payouts, Payout{Address: p, Amount: amounts[i]})
			res.Fee -= amounts[i]
		}
	}
	return res, nil
}

// v0 - Unaudited: This is an initial version that has not yet been formally audited.
// Use in production at your own risk.
//
// Package payout defines how the stakes of a gnofly arena round are shared
// out once the round is over: a Rule turns what happened, who died and by
// whose hand, into who gets what.
//
// The package is pure: it holds no state, moves no coin and knows nothing
// about roles. A realm keeps the stakes, asks a rule for a Result and makes
// the payments itself:
//
//	players, err := payout.ParsePlayers("g1aaa...,g1bbb...,g1ccc...")
//	if err != nil {
//		panic(err)
//	}
//	deaths, err := payout.ParseDeaths("g1bbb...:g1aaa...;g1ccc...:")
//	if err != nil {
//		panic(err)
//	}
//	g := payout.Game{Stake: 10000000, Lives: 3, KillTarget: 0, FeeBps: 500}
//	res, err := payout.Lookup(payout.ModeDeathmatch).Settle(g, players, deaths)
//
// Two rules ship with the package, both stateless values with no field:
//
//   - BattleRoyale: the pot goes to the players still in at the end, or to
//     the last one out;
//   - Deathmatch: the pot goes to the top three by kills, 60%, 30% and 10%.
//
// Every rule conserves the pot. For any input a rule accepts,
//
//	sum(res.Payouts) + res.Fee == Stake * len(players)
//
// and nobody but a player of the round is ever paid. What is not paid to a
// player is the house's cut, the fee. Amounts are rounded down, and what
// rounding leaves over goes to the fee. A realm that pays out real coins
// should still check both properties on the Result it gets before it sends
// anything: that check is cheap, and it is what keeps a mistake in a rule
// from becoming a loss.
package payout

package payout

// Both parsers read their input in a single pass, byte by byte, and bound it
// before they read it. On chain every interpreted operation is paid for, and
// an oversized string must cost its sender nothing but a refusal.
//
// They only accept an address in its canonical form, see validAddress.

const (
	// addressLen is the length of a gno address: "g1" and 38 characters.
	addressLen = 40
	// maxPlayersLen bounds a players string: MaxPlayers addresses, each
	// followed by a separator.
	maxPlayersLen = MaxPlayers * (addressLen + 1)
	// maxDeathsLen bounds a deaths string: MaxDeaths entries
	// of two addresses, each followed by a separator.
	maxDeathsLen = MaxDeaths * 2 * (addressLen + 1)
)

// ParsePlayers parses a players string: comma-separated addresses, for
// example
//
//	g1aaa...,g1bbb...,g1ccc...
//
// It returns 1 to MaxPlayers addresses in the order of the string, each one
// valid and listed once. Whitespace, empty entries and a trailing separator
// are refused. Whether there are enough players for a round is decided by
// Rule.Settle, and by the realm that starts the round.
func ParsePlayers(s string) ([]address, error) {
	if s == "" {
		return nil, ErrNoPlayers
	}
	if len(s) > maxPlayersLen {
		return nil, ErrTooManyPlayers
	}
	var players []address
	i := 0
	for {
		if len(players) == MaxPlayers {
			return nil, ErrTooManyPlayers
		}
		end := indexFrom(s, i, ',')
		addr := address(s[i:end])
		if !validAddress(addr) {
			return nil, ErrPlayersFormat
		}
		if indexOf(players, addr) >= 0 {
			return nil, ErrDuplicatePlayer
		}
		players = append(players, addr)
		if end == len(s) {
			return players, nil
		}
		i = end + 1
		if i == len(s) {
			return nil, ErrPlayersFormat // a trailing ","
		}
	}
}

// ParseDeaths parses a deaths string: "victim:killer" entries
// separated by ";", in the order they happened, "victim:" when nobody shot
// the victim down, for example
//
//	g1bbb...:g1aaa...;g1ccc...:
//
// The empty string means nobody died and gives an empty list. At
// most MaxDeaths entries are accepted, and every address must be valid.
// Whitespace, empty entries and a trailing separator are refused.
//
// It only checks the syntax. Whether the victims and the killers are players
// of the round, and how often they died, is decided by Rule.Settle.
func ParseDeaths(s string) ([]Death, error) {
	if s == "" {
		return nil, nil
	}
	if len(s) > maxDeathsLen {
		return nil, ErrTooManyDeaths
	}
	var out []Death
	i := 0
	for {
		if len(out) == MaxDeaths {
			return nil, ErrTooManyDeaths
		}
		colon := indexFrom(s, i, ':')
		if colon == len(s) {
			return nil, ErrDeathsFormat
		}
		end := indexFrom(s, colon+1, ';')

		victim := address(s[i:colon])
		if !validAddress(victim) {
			return nil, ErrDeathsFormat
		}
		killer := address(s[colon+1 : end])
		if killer != "" && !validAddress(killer) {
			return nil, ErrDeathsFormat
		}
		out = append(out, Death{Victim: victim, Killer: killer})
		if end == len(s) {
			return out, nil
		}
		i = end + 1
		if i == len(s) {
			return nil, ErrDeathsFormat // a trailing ";"
		}
	}
}

// validAddress reports whether addr is a valid address in its canonical,
// lowercase form.
//
// Bech32 can also be written in all capitals, and address.IsValid accepts
// that. To a realm the capitals would be a second name for the same account,
// one that matches no player of a round. Bech32 does not allow mixing cases,
// so looking at the first character is enough. The length is checked first:
// it is free, and it keeps an overlong string away from the decoder.
func validAddress(addr address) bool {
	return len(addr) == addressLen && addr[0] == 'g' && addr.IsValid()
}

// indexFrom returns the index of the first c in s at or after i, or len(s)
// when there is none.
func indexFrom(s string, i int, c byte) int {
	for i < len(s) && s[i] != c {
		i++
	}
	return i
}

package payout

import "errors"

// Death is one life lost in a round: Victim was shot down by Killer, or by
// nobody (a crash, a disconnect). A pilot dies up to Game.Lives times and is
// out after the last one.
type Death struct {
	Victim address
	Killer address // "" when nobody shot the victim down
}

// Game is what a rule needs to know about the arena a round was played in.
type Game struct {
	Stake      int64 // ugnot, what each player paid
	Lives      int64 // deaths a player can take, the last one puts them out
	KillTarget int64 // kills that end the round, 0 for the clock only
	FeeBps     int64 // the house's share, in basis points
}

// Payout is an amount of ugnot to send to an address.
type Payout struct {
	Address address
	Amount  int64 // ugnot
}

// Result is what a rule decides: who gets what, and the house's cut.
type Result struct {
	Payouts []Payout // in the order of the players, players paid nothing left out
	Fee     int64
}

// Rule turns what happened in a round into who gets what.
type Rule interface {
	Mode() string
	Settle(g Game, players []address, deaths []Death) (Result, error)
}

// The modes of the rules shipped with the package.
const (
	ModeBattleRoyale = "battle-royale"
	ModeDeathmatch   = "deathmatch"
)

// Bounds every rule enforces.
const (
	MinPlayers    = 2
	MaxPlayers    = 8
	MinLives      = 1
	MaxLives      = 3
	MaxKillTarget = 20
	MinStake      = 1             // ugnot
	MaxStake      = 1000000000000 // ugnot, 1e12
	BpsScale      = 10000         // basis points in a whole
	MaxFeeBps     = 5000          // the fee never takes more than half
	MaxDeaths     = MaxPlayers * MaxLives
)

var (
	ErrStake           = errors.New("payout: stake must be between 1 and 1000000000000 ugnot")
	ErrLives           = errors.New("payout: lives must be between 1 and 3")
	ErrKillTarget      = errors.New("payout: the kill target must be between 0 and 20")
	ErrFee             = errors.New("payout: the fee must be between 0 and 5000 bps")
	ErrTooFewPlayers   = errors.New("payout: at least 2 players are required")
	ErrTooManyPlayers  = errors.New("payout: at most 8 players are allowed")
	ErrEmptyPlayer     = errors.New("payout: a player has no address")
	ErrDuplicatePlayer = errors.New("payout: a player is listed twice")
	ErrUnknownVictim   = errors.New("payout: a victim is not a player of the round")
	ErrDeadTooOften    = errors.New("payout: a player died more often than they have lives")
	ErrUnknownKiller   = errors.New("payout: a killer is not a player of the round")
	ErrSelfKill        = errors.New("payout: a player cannot be their own killer")
	ErrTooManyDeaths   = errors.New("payout: more deaths than lives in the round")

	ErrNoPlayers     = errors.New("payout: players must list at least one address")
	ErrPlayersFormat = errors.New("payout: players must be comma-separated addresses")
	ErrDeathsFormat  = errors.New(`payout: deaths must be "victim:killer" entries separated by ";"`)
)

// Lookup returns the rule of a mode, or nil for a mode nobody knows.
func Lookup(mode string) Rule {
	switch mode {
	case ModeBattleRoyale:
		return BattleRoyale{}
	case ModeDeathmatch:
		return Deathmatch{}
	}
	return nil
}

// Modes lists the modes of the shipped rules. The slice is a fresh copy.
func Modes() []string {
	return []string{ModeBattleRoyale, ModeDeathmatch}
}

// tally is what happened in a round, per player.
type tally struct {
	deaths  []int64 // lives each player lost
	kills   []int64 // deaths credited to each player
	lastOut int     // the player whose last life went last, -1 when nobody is out
	first   int     // the first player to reach the kill target, -1 when nobody did
}

// out reports whether player i lost every life.
func (t tally) out(i int, lives int64) bool {
	return t.deaths[i] >= lives
}

// check enforces what every rule requires, and counts deaths and kills.
//
// A killer may be out already: a bullet still in flight. A dead pilot cannot
// die again, though: a victim takes at most Lives deaths.
func check(g Game, players []address, deaths []Death) (tally, error) {
	if g.Stake < MinStake || g.Stake > MaxStake {
		return tally{}, ErrStake
	}
	if g.Lives < MinLives || g.Lives > MaxLives {
		return tally{}, ErrLives
	}
	if g.KillTarget < 0 || g.KillTarget > MaxKillTarget {
		return tally{}, ErrKillTarget
	}
	if g.FeeBps < 0 || g.FeeBps > MaxFeeBps {
		return tally{}, ErrFee
	}
	n := len(players)
	if n < MinPlayers {
		return tally{}, ErrTooFewPlayers
	}
	if n > MaxPlayers {
		return tally{}, ErrTooManyPlayers
	}
	for i, p := range players {
		if p == "" {
			return tally{}, ErrEmptyPlayer
		}
		if indexOf(players[:i], p) >= 0 {
			return tally{}, ErrDuplicatePlayer
		}
	}
	if int64(len(deaths)) > int64(n)*g.Lives {
		return tally{}, ErrTooManyDeaths
	}

	t := tally{deaths: make([]int64, n), kills: make([]int64, n), lastOut: -1, first: -1}
	for _, d := range deaths {
		victim := indexOf(players, d.Victim)
		if victim < 0 {
			return tally{}, ErrUnknownVictim
		}
		if t.out(victim, g.Lives) {
			return tally{}, ErrDeadTooOften
		}
		if d.Killer != "" {
			if d.Killer == d.Victim {
				return tally{}, ErrSelfKill
			}
			killer := indexOf(players, d.Killer)
			if killer < 0 {
				return tally{}, ErrUnknownKiller
			}
			t.kills[killer]++
			if g.KillTarget > 0 && t.first < 0 && t.kills[killer] >= g.KillTarget {
				t.first = killer
			}
		}
		t.deaths[victim]++
		if t.out(victim, g.Lives) {
			t.lastOut = victim
		}
	}
	return t, nil
}

func indexOf(list []address, addr address) int {
	for i, a := range list {
		if a == addr {
			return i
		}
	}
	return -1
}

// afterFee returns what is left of amount once the fee is taken.
func afterFee(amount, feeBps int64) int64 {
	return amount * (BpsScale - feeBps) / BpsScale
}

package arena

import (
	"strconv"
	"time"

	"gno.land/p/nt/bptree/v0"
)

// The whole state of the realm. Everything is unexported and nothing below is
// ever returned by reference: the trees are /p/ types with mutator methods,
// so handing one out would be handing out write access to the realm.
var (
	version int64 // bumps on every admin write, see Version

	// Arenas exist from the first paid entry until their game is over, or
	// their lobby is empty. An arena nobody paid into is never stored.
	arenas bptree.BPTree // arena id -> *arena, with its lobby and its round

	// The last games played, for readers: their result, by arena id, and the
	// ids in the order they closed, oldest first.
	results bptree.BPTree // arena id -> encoded result, see results.gno
	closed  []string

	refundDelay int64 // seconds after a game's time limit before anyone may refund it

	escrowed int64 // ugnot owed to players: the stakes of every lobby and running game, and their unclaimed winnings

	// Winnings not claimed yet, see claims.gno.
	claims bptree.BPTree // player address -> encoded credits

	// What players won, see earnings.gno.
	earnings bptree.BPTree // player address -> encoded totals, allocated on a first settled game
	winners  ranking       // the top players by winnings

	webPath string // "/r/g1t2kg2vtr3fukg43eujkn6x53gfdyakhngt4sfd/gnofly/arena/v0", used to build links in Render
)

const defaultRefundDelay = 600 // seconds

// init runs once, when the package is added to the chain. Unlike the game
// realm this one has nothing to remember about its deployer: it has no role
// of its own.
func init(cur realm) {
	bootstrap(cur.PkgPath())
}

// bootstrap (re)creates the initial state. The tests call it to start from a
// clean slate.
func bootstrap(pkgPath string) {
	arenas = bptree.BPTree{}
	results = bptree.BPTree{}
	closed = nil
	refundDelay = defaultRefundDelay
	escrowed = 0
	claims = bptree.BPTree{}
	earnings = bptree.BPTree{}
	winners = ranking{}
	webPath = webPathOf(pkgPath)
	version = 1
}

// Version returns a counter that bumps on every admin write: the refund
// delay. Player and referee actions do not bump it.
func Version() int64 {
	return version
}

// now returns the block time in Unix seconds.
func now() int64 {
	return time.Now().Unix()
}

// webPathOf turns "gno.land/r/..." into "/r/...".
func webPathOf(pkgPath string) string {
	for i := 0; i < len(pkgPath); i++ {
		if pkgPath[i] == '/' {
			return pkgPath[i:]
		}
	}
	return ""
}

func itoa(n int64) string {
	return strconv.FormatInt(n, 10)
}

package arena

import (
	"chain"
	"strings"
)

// Winnings are not sent when a game settles. They are credited to each
// winner, stay in the escrow, and the winner takes them with Claim, every
// game at once. A settlement then moves no coin to a player, and a player
// who never comes back costs nobody anything.
//
// Refunds (Leave, CancelRound, RefundRound, ExpireLobby) still send the
// stakes back straight away: a refund is not a win.

// claimCredit is what one game owes one player.
type claimCredit struct {
	id     string
	amount int64
}

// The credits of a player are stored as one string, oldest first:
//
//	<arena id>:<amount>,<arena id>:<amount>

func creditsOf(addr address) []claimCredit {
	v := claims.Get(addr.String())
	if v == nil {
		return nil
	}
	var out []claimCredit
	for _, entry := range strings.Split(v.(string), ",") {
		colon := indexFrom(entry, 0, ':')
		if colon == 0 || colon == len(entry) {
			panic(errCorruptClaims)
		}
		amount, ok := digits(entry[colon+1:])
		if !ok || amount <= 0 {
			panic(errCorruptClaims)
		}
		out = append(out, claimCredit{id: entry[:colon], amount: amount})
	}
	return out
}

// credit owes amount to a player for the game of an arena. The coins are
// already in the realm: they stay in the escrow until claimed.
func credit(addr address, id string, amount int64) {
	if amount <= 0 {
		return
	}
	entry := id + ":" + itoa(amount)
	if v := claims.Get(addr.String()); v != nil {
		entry = v.(string) + "," + entry
	}
	claims.Set(addr.String(), entry)
	hold(amount)
}

// Claim sends the caller everything the realm owes them from settled
// games, and returns the amount in ugnot. It panics when there is nothing
// to claim.
func Claim(cur realm) int64 {
	player := callerOf(0, cur)
	list := creditsOf(player)
	if len(list) == 0 {
		panic(errNothingToClaim)
	}
	total := int64(0)
	for _, c := range list {
		total += c.amount
	}
	// State first: nothing is owed any more before the coins leave.
	claims.Remove(player.String())
	release(total)
	pay(0, cur, player, total)
	assertSolvent(0, cur)
	chain.Emit("Claimed", "player", player.String(), "amount", itoa(total), "games", itoa(int64(len(list))))
	return total
}

// Claimable returns what a player can claim, in ugnot.
func Claimable(addr address) int64 {
	total := int64(0)
	for _, c := range creditsOf(addr) {
		total += c.amount
	}
	return total
}

// ClaimsJSON returns what a player can claim, game by game, oldest first:
//
//	{ "address": "g1...", "total": 19000000, "games": [ { "id": "...", "amount": 19000000 } ] }
//
// The output has no whitespace. An address with nothing to claim returns
// the same shape with a zero total and no game.
func ClaimsJSON(addr address) string {
	list := creditsOf(addr)
	var b strings.Builder
	total := int64(0)
	for _, c := range list {
		total += c.amount
	}
	b.WriteString(`{"address":` + quote(addr.String()) + `,"total":` + itoa(total) + `,"games":[`)
	for i, c := range list {
		if i > 0 {
			b.WriteByte(',')
		}
		b.WriteString(`{"id":"` + c.id + `","amount":` + itoa(c.amount) + `}`)
	}
	b.WriteString("]}")
	return b.String()
}

// v0 - Unaudited: This is an initial version that has not yet been formally audited.
// Use in production at your own risk.
//
// Package arena holds the paid games of gnofly, a multiplayer plane game. A
// player pays an entry price in ugnot to join a game, the realm keeps the
// stakes until the game is over, then credits them by a rule it applies
// itself. Winners take what they are owed with Claim.
//
// Games are created off chain, by the game server at a player's request, and
// described by a spec (see spec.gno): mode, entry price, seats, lives, game
// time and kill target. The realm only stores a game once someone paid for
// it, and forgets it when it is over or its lobby empties: no game nobody
// played is ever left on chain.
//
// Four kinds of callers write to it:
//
//   - players enter a game with their stake attached, the first one handing
//     the realm its spec, and may leave again until it starts (Enter, Leave);
//   - referees, the game servers, start a game with the players of its lobby,
//     and report who died by whose hand when it is over (StartRound,
//     SettleRound, CancelRound);
//   - anyone can send the stakes of a game back to its players once the
//     referee is long overdue, and close a lobby whose game never started an
//     hour after it was created (RefundRound, ExpireLobby);
//   - the admins of the game realm set the refund delay (SetRefundDelay).
//
// The realm keeps no roles of its own: the owner, the admins, the referees
// and the treasury are those of gno.land/r/g1t2kg2vtr3fukg43eujkn6x53gfdyakhngt4sfd/gnofly/game/v0, asked at
// the time of each call.
//
// The referee is trusted for facts only: who died, and by whom. What these
// facts are worth is decided by a rule of
// gno.land/p/g1t2kg2vtr3fukg43eujkn6x53gfdyakhngt4sfd/gnofly/arena/payout/v0, picked by the mode of the game,
// and the realm checks what the rule returns before it sends anything.
//
// # Money
//
// The realm owes exactly the stakes of its lobbies and of its running
// games, and the winnings not claimed yet, and counts them in one number,
// see Escrowed. Every coin that leaves
// goes to a player of the game it came from, or to the treasury of the game
// realm:
//
//	Enter        +stake   the envelope of the call stays in the realm
//	Leave        -stake   back to the player
//	ExpireLobby  -stakes  back to the players of the lobby
//	StartRound    0       stakes move from the lobby to the game
//	SettleRound  -fee     the fee leaves, the rest is credited to the winners
//	Claim        -owed    everything credited to the caller, every game at once
//	CancelRound  -pot     back to the players of the game
//	RefundRound  -pot     back to the players of the game
//
// A game is closed by exactly one of SettleRound, CancelRound and
// RefundRound, once.
//
// What a settlement does not pay to the players is the house's cut, a fee of
// 5% sent to the treasury of the game realm, rounding included.
//
// Reads are plain functions meant for vm/qeval. The ones ending in JSON
// return a single string holding a JSON document. Render exposes the same
// data as markdown for gnoweb.
package arena

package arena

import "gno.land/p/g1t2kg2vtr3fukg43eujkn6x53gfdyakhngt4sfd/gnofly/arena/payout/v0"

// Earnings are what players won, added up round after round. Like the
// results they are a record for readers: no payment is ever computed from
// them.
//
// For one settled round a player's winnings are what they were paid above
// their own stake, and never less than zero: losing a stake does not take
// anything back from what was won before. Cancelled and refunded rounds
// count for nothing, nobody won or lost in them.

// topSize is how many players the list of top winners holds.
const topSize = 10

// totals is what the realm remembers about one player.
type totals struct {
	won    int64 // ugnot won above the stakes, over every settled round
	rounds int64 // settled rounds played
}

// Totals are stored as a single string, "won:rounds", for the same reason
// as the pilots of the game realm: a struct would be one more stored object
// per player, and the referee pays for up to 16 new players per settlement.

// encode returns the stored form of t.
func (t totals) encode() string {
	return itoa(t.won) + ":" + itoa(t.rounds)
}

// totalsOf returns the totals of a player, zero for a player who never
// finished a round.
func totalsOf(addr address) totals {
	v := earnings.Get(addr.String())
	if v == nil {
		return totals{}
	}
	s := v.(string)
	colon := indexFrom(s, 0, ':')
	if colon == len(s) {
		panic(errCorruptEarnings)
	}
	won, ok := digits(s[:colon])
	if !ok {
		panic(errCorruptEarnings)
	}
	rounds, ok := digits(s[colon+1:])
	if !ok {
		panic(errCorruptEarnings)
	}
	return totals{won: won, rounds: rounds}
}

// creditRound records a settled round for each of its players: one more
// round played, and what they were paid above their stake, if anything.
func creditRound(stake int64, players []address, payouts []payout.Payout) {
	for _, p := range players {
		gain := int64(0)
		for _, paid := range payouts {
			if paid.Address == p && paid.Amount > stake {
				gain = paid.Amount - stake
			}
		}

		t := totalsOf(p)
		before := t.won
		t.won += gain
		t.rounds++
		earnings.Set(p.String(), t.encode())

		if gain > 0 {
			if next, changed := winners.raise(p, before, t.won, topSize); changed {
				winners = next
			}
		}
	}
}

// ranking is the list of top winners: the players who won the most, best
// first, at most topSize lines and one line per player. With equal winnings,
// the player who got there first stays ahead.
//
// It is the ranking of the game realm. It is kept sorted at write time, so
// reading it never has to look at every player. Winnings only going up is
// what makes that exact: a player outside the list can only enter it through
// raise.
//
// The two slices are parallel: slices of plain values are one stored object
// each, where a slice of structs would be one object per line.
type ranking struct {
	addrs  []address
	scores []int64
}

// raise puts a player at their place after their score went up from old to
// score. It returns the ranking to store, and changed == false when it is
// left as it is: the player is not on a full list and still not good enough
// to get on.
func (r ranking) raise(addr address, old, score int64, size int) (next ranking, changed bool) {
	from := r.lineOf(addr, old)
	to := r.search(score - 1) // after every line with this score or more
	if from < 0 && to >= size {
		return r, false
	}
	if from >= 0 && to > from {
		to = from // cannot happen: a score only goes up
	}
	next = ranking{
		addrs:  spliceAddrs(r.addrs, from, to, addr, size),
		scores: spliceInts(r.scores, from, to, score, size),
	}
	return next, true
}

// search returns the index of the first line with a score of limit or less,
// the number of lines when there is none. The list is sorted, so this is a
// binary search.
func (r ranking) search(limit int64) int {
	lo, hi := 0, len(r.scores)
	for lo < hi {
		mid := (lo + hi) / 2
		if r.scores[mid] <= limit {
			hi = mid
		} else {
			lo = mid + 1
		}
	}
	return lo
}

// lineOf returns the index of a player's line, -1 when they have none. old
// is the player's score before the change being applied.
//
// A line always carries the current score of its player, because every
// change of a score goes through raise. So the line can only be among those
// with exactly old. A player whose score was zero has never been through
// raise and has no line.
func (r ranking) lineOf(addr address, old int64) int {
	if old <= 0 {
		return -1
	}
	for i := r.search(old); i < len(r.scores) && r.scores[i] == old; i++ {
		if r.addrs[i] == addr {
			return i
		}
	}
	return -1
}

// spliceAddrs returns a copy of a ranking column with v inserted at index
// to. With from >= 0 the element at that index, the player's previous line,
// is left out; to must not be past it. With from < 0 the result is kept to
// size elements by dropping the tail; to must be below size.
//
// The copy has exactly the length of its content, so that nothing else stays
// in storage.
func spliceAddrs(list []address, from, to int, v address, size int) []address {
	if from < 0 {
		if len(list) >= size {
			list = list[:size-1]
		}
		out := make([]address, 0, len(list)+1)
		out = append(out, list[:to]...)
		out = append(out, v)
		return append(out, list[to:]...)
	}
	out := make([]address, 0, len(list))
	out = append(out, list[:to]...)
	out = append(out, v)
	out = append(out, list[to:from]...)
	return append(out, list[from+1:]...)
}

// spliceInts is spliceAddrs for a column of numbers.
func spliceInts(list []int64, from, to int, v int64, size int) []int64 {
	if from < 0 {
		if len(list) >= size {
			list = list[:size-1]
		}
		out := make([]int64, 0, len(list)+1)
		out = append(out, list[:to]...)
		out = append(out, v)
		return append(out, list[to:]...)
	}
	out := make([]int64, 0, len(list))
	out = append(out, list[:to]...)
	out = append(out, v)
	out = append(out, list[to:from]...)
	return append(out, list[from+1:]...)
}

package arena

import (
	"chain"
	"chain/banker"
)

// The money of the realm goes through the four functions below and nowhere
// else.
//
// escrowed is what the realm owes: the stakes of every lobby and of every
// running round, in ugnot. It goes up in hold, when a player enters, and
// down in release, before coins leave. The balance of the realm's address is
// what it has. The rule of this file is
//
//	balance >= escrowed, and balance == escrowed unless someone gave coins away
//
// Coins can only come in through Enter: the chain refuses a call that
// attaches coins to a function that does not read them. Someone can still
// send coins straight to the realm's address with a bank transfer. Such
// coins are owed to nobody, no function spends them, and they stay there.
//
// Every function that moves money ends with assertSolvent. If a mistake in
// this realm ever made a path send more than it released, the realm would be
// paying one player with the stake of another: the check turns that into an
// aborted transaction, which takes the payments back with it.

// payDenom is the only coin the realm deals in.
const payDenom = "ugnot"

// hold records that the realm received amount in stakes.
func hold(amount int64) {
	if amount <= 0 {
		panic(errEscrow)
	}
	escrowed += amount
}

// release takes amount out of what the realm owes. It is called before the
// coins are sent, and it panics rather than let the counter go below zero.
func release(amount int64) {
	if amount <= 0 || amount > escrowed {
		panic(errEscrow)
	}
	escrowed -= amount
}

// pay sends amount ugnot from the realm's own balance to an address.
//
// A RealmSend banker can spend everything the realm holds, which is why it
// is built here and only here, from the live cur of the crossing function
// (rlm), and never kept. The bank aborts the transaction if the realm does
// not have the coins.
func pay(_ int, rlm realm, to address, amount int64) {
	if amount <= 0 {
		panic(errEscrow)
	}
	coins := chain.NewCoins(chain.NewCoin(payDenom, amount))
	banker.NewBanker(banker.BankerTypeRealmSend, rlm).SendCoins(rlm.Address(), to, coins)
}

// assertSolvent panics unless the realm holds at least what it owes.
func assertSolvent(_ int, rlm realm) {
	if banker.NewReadonlyBanker().GetCoin(rlm.Address(), payDenom) < escrowed {
		panic(errInsolvent)
	}
}

// Escrowed returns what the realm owes to players, in ugnot: the stakes of
// every lobby and of every running round. The balance of the realm's
// address is never below it.
func Escrowed() int64 {
	return escrowed
}

package arena

import "strings"

// The JSON documents are built by hand. That is safe because every string
// that reaches them was validated against a JSON-safe charset when it was
// written: ids are hex, modes and nonces [a-z0-9-], tickets hex, addresses
// bech32. The one string that is not under the realm's control, an address
// typed into a query, goes through quote.
//
// Ordering is deterministic everywhere: arenas follow their id (the tree
// iterates in key order), a lobby and a round the order of entry, results
// are newest first and earnings best first.

// ArenasJSON returns every arena someone paid into and whose game is not
// over, as a JSON array sorted by id:
//
//	[
//	  { "id": "3f2a...", "mode": "deathmatch", "stake": 10000000,
//	    "minSeats": 2, "maxSeats": 8, "lives": 3, "seconds": 900, "killTarget": 5,
//	    "creator": "g1...", "created": 1790950000, "nonce": "k3x9",
//	    "lobby": [ { "address": "g1...", "ticket": "9f86d0...00a08" } ],
//	    "round": { "startedAt": 1790950300, "players": [ "g1...", "g1..." ] } }
//	]
//
// The output has no whitespace. "round" is null until the game starts.
// The fields from "mode" to "nonce" are the arena's spec: the game server
// rebuilds the spec string, and so the id, from them.
func ArenasJSON() string {
	var b strings.Builder
	b.WriteByte('[')
	first := true
	arenas.Iterate("", "", func(id string, v any) bool {
		if !first {
			b.WriteByte(',')
		}
		first = false
		writeArena(&b, id, v.(*arena))
		return false
	})
	b.WriteByte(']')
	return b.String()
}

// ArenaJSON returns one arena in the shape of ArenasJSON, or null.
func ArenaJSON(id string) string {
	a := getArena(id)
	if a == nil {
		return "null"
	}
	var b strings.Builder
	writeArena(&b, id, a)
	return b.String()
}

func writeArena(b *strings.Builder, id string, a *arena) {
	b.WriteString(`{"id":"` + id + `","mode":"` + a.mode + `"`)
	for _, f := range []struct {
		k string
		v int64
	}{{"stake", a.stake}, {"minSeats", a.minSeats}, {"maxSeats", a.maxSeats}, {"lives", a.lives},
		{"seconds", a.seconds}, {"killTarget", a.killTarget}} {
		b.WriteString(`,"` + f.k + `":` + itoa(f.v))
	}
	b.WriteString(`,"creator":"` + a.creator.String() + `","created":` + itoa(a.created) + `,"nonce":"` + a.nonce + `"`)
	b.WriteString(`,"lobby":[`)
	for i, p := range a.lobby {
		if i > 0 {
			b.WriteByte(',')
		}
		b.WriteString(`{"address":"` + p.String() + `","ticket":"` + a.tickets[i] + `"}`)
	}
	b.WriteString(`],"round":`)
	if a.round == nil {
		b.WriteString("null}")
		return
	}
	b.WriteString(`{"startedAt":` + itoa(a.round.startedAt) + `,"players":[`)
	for i, p := range a.round.players {
		if i > 0 {
			b.WriteByte(',')
		}
		b.WriteString(`"` + p.String() + `"`)
	}
	b.WriteString("]}}")
}

// ResultsJSON returns the last closed games, newest first, at most 50:
//
//	[ { "id": "3f2a...", "mode": "deathmatch", "stake": 10000000,
//	    "outcome": "settled", "players": 2, "pot": 20000000, "fee": 500000,
//	    "closedAt": 1790951000,
//	    "payouts": [ { "address": "g1...", "amount": 19500000 } ] } ]
func ResultsJSON() string {
	var b strings.Builder
	b.WriteByte('[')
	for i := len(closed) - 1; i >= 0; i-- {
		if i < len(closed)-1 {
			b.WriteByte(',')
		}
		r, _ := resultOf(closed[i])
		writeResult(&b, closed[i], r)
	}
	b.WriteByte(']')
	return b.String()
}

// ResultJSON returns the result of one closed game in the shape of
// ResultsJSON, or null when the realm does not have it (still running, or
// too old).
func ResultJSON(id string) string {
	r, ok := resultOf(id)
	if !ok {
		return "null"
	}
	var b strings.Builder
	writeResult(&b, id, r)
	return b.String()
}

func writeResult(b *strings.Builder, id string, r result) {
	b.WriteString(`{"id":"` + id + `","mode":"` + r.mode + `","stake":` + itoa(r.stake) +
		`,"outcome":"` + r.outcome + `","players":` + itoa(r.players) + `,"pot":` + itoa(r.pot) +
		`,"fee":` + itoa(r.fee) + `,"closedAt":` + itoa(r.closedAt) + `,"payouts":[`)
	for i, p := range r.payouts {
		if i > 0 {
			b.WriteByte(',')
		}
		b.WriteString(`{"address":"` + p.Address.String() + `","amount":` + itoa(p.Amount) + `}`)
	}
	b.WriteString("]}")
}

// EarningsJSON returns the top winners as a JSON array, best first, at most
// 10 entries:
//
//	[ { "address": "g1...", "won": 19000000, "rounds": 3 } ]
//
// The output has no whitespace. "won" adds up, round after round, what the
// player was paid above their own stake, never less than zero for a round.
// "rounds" is how many settled rounds they played. With equal winnings, the
// player who got there first stays ahead.
func EarningsJSON() string {
	var b strings.Builder
	b.WriteByte('[')
	for i, addr := range winners.addrs {
		if i > 0 {
			b.WriteByte(',')
		}
		writeTotals(&b, `"`+addr.String()+`"`, totalsOf(addr))
	}
	b.WriteByte(']')
	return b.String()
}

// PlayerJSON returns one player's totals as a JSON object:
//
//	{ "address": "g1...", "won": 19000000, "rounds": 3 }
//
// The output has no whitespace. An unknown address returns the same shape
// with zero won and zero rounds.
func PlayerJSON(addr address) string {
	var b strings.Builder
	writeTotals(&b, quote(addr.String()), totalsOf(addr))
	return b.String()
}

// writeTotals writes the totals of a player. quoted is the player's address
// as a JSON string literal, quotes included.
func writeTotals(b *strings.Builder, quoted string, t totals) {
	b.WriteString(`{"address":`)
	b.WriteString(quoted)
	b.WriteString(`,"won":`)
	b.WriteString(itoa(t.won))
	b.WriteString(`,"rounds":`)
	b.WriteString(itoa(t.rounds))
	b.WriteByte('}')
}

// quote returns s as a JSON string literal, quotes included. It is for the
// strings the realm did not validate. Quotes and backslashes are escaped and
// anything outside printable ASCII is replaced by "?", so the result is
// valid JSON whatever s holds.
func quote(s string) string {
	var b strings.Builder
	b.WriteByte('"')
	for i := 0; i < len(s); i++ {
		c := s[i]
		switch {
		case c == '"' || c == '\\':
			b.WriteByte('\\')
			b.WriteByte(c)
		case c < 0x20 || c > 0x7e:
			b.WriteByte('?')
		default:
			b.WriteByte(c)
		}
	}
	b.WriteByte('"')
	return b.String()
}

package arena

import (
	"chain"

	// Only for OriginSend, in Enter. Caller identity always comes from
	// cur.Previous(), never from this package.
	"chain/runtime/unsafe"
)

// arena is one game: its spec, the players who paid and wait, and once it
// started, its round. It is stored from the first paid entry and deleted
// when its round is closed or its lobby empties.
type arena struct {
	spec
	lobby   []address
	tickets []string // SHA-256 of each player's secret, 64 hex characters
	round   *round   // nil until the game starts
}

func getArena(id string) *arena {
	v := arenas.Get(id)
	if v == nil {
		return nil
	}
	return v.(*arena)
}

func mustArena(id string) *arena {
	a := getArena(id)
	if a == nil {
		panic(errUnknownArena)
	}
	return a
}

// Enter puts the caller in the lobby of the arena that spec describes, and
// returns its id. The exact stake must be attached to the transaction
// (-send "<stake>ugnot") and stays in the realm until the player leaves or
// the game is over.
//
// The first entry creates the arena, the next ones join it: the realm
// recomputes the id from the spec every time. An arena takes entries for an
// hour after it was created, and until its game starts.
//
// ticket is 64 lowercase hex characters, the SHA-256 of a secret the
// player's client made up: the game server gives the seat to whoever shows
// the secret.
//
// It must be called directly by a user (maketx call): a call relayed by
// another realm or by a maketx run script is refused.
func Enter(cur realm, spec string, ticket string) string {
	player := callerOf(0, cur)
	// Paid-call guard: two checks that are only correct together.
	//
	// (a) The caller is a plain user account. Only then is the -send
	//     envelope guaranteed to have landed at this realm's address. A
	//     relaying realm or a maketx run script can attach coins to the
	//     transaction and keep them, while OriginSend still reports them.
	if !cur.Previous().IsUserCall() {
		panic(errNotUserCall)
	}
	sp := parseSpec(spec)
	id := idOf(spec)
	t := now()
	if t > sp.created+entryWindow {
		panic(errEntryClosed)
	}
	if sp.created > t+clockSkew {
		panic(errNotYetCreated)
	}
	if !validTicket(ticket) {
		panic(errInvalidTicket)
	}
	a := getArena(id)
	if a == nil {
		a = &arena{spec: sp}
	}
	if a.round != nil {
		panic(errRoundRunning)
	}
	if indexOfAddr(a.lobby, player) >= 0 {
		panic(errAlreadyInLobby)
	}
	if int64(len(a.lobby)) >= a.maxSeats {
		panic(errLobbyFull)
	}
	// (b) The envelope is exactly the stake: one coin, the right denom, the
	//     right amount. Anything else would either underpay or leave coins
	//     in the realm that it owes to nobody.
	sent := unsafe.OriginSend()
	if len(sent) != 1 || sent[0].Denom != payDenom || sent[0].Amount != a.stake {
		panic("gnofly: wrong payment, send exactly " + itoa(a.stake) + payDenom)
	}

	// The coins are already at the realm's address: the chain moved them
	// before the call. All that is left is to write down who they belong to.
	a.lobby = withAddr(a.lobby, player)
	a.tickets = withString(a.tickets, ticket)
	arenas.Set(id, a)
	hold(a.stake)
	// The guard above says the coins arrived. This looks at the balance.
	assertSolvent(0, cur)

	chain.Emit("Entered",
		"arena", id,
		"player", player.String(),
		"stake", itoa(a.stake),
		"ticket", ticket,
		"lobby", itoa(int64(len(a.lobby))),
	)
	return id
}

// Leave takes the caller out of the lobby of an arena and sends their stake
// back. It works until the game starts. The last player out deletes the
// arena: nothing is left on chain of a game nobody played.
func Leave(cur realm, id string) {
	player := callerOf(0, cur)
	a := mustArena(id)
	seat := indexOfAddr(a.lobby, player)
	if seat < 0 {
		panic(errNotInLobby)
	}
	a.lobby = withoutAddr(a.lobby, seat)
	a.tickets = withoutString(a.tickets, seat)
	if len(a.lobby) == 0 {
		arenas.Remove(id)
	}
	release(a.stake)

	pay(0, cur, player, a.stake)
	assertSolvent(0, cur)

	chain.Emit("Left",
		"arena", id,
		"player", player.String(),
		"stake", itoa(a.stake),
	)
}

// ExpireLobby closes an arena whose game never started: every player in the
// lobby gets their stake back, and the arena is deleted. Anyone can call it
// once the arena stopped taking entries, an hour after it was created.
func ExpireLobby(cur realm, id string) {
	caller := callerOf(0, cur)
	a := mustArena(id)
	if a.round != nil {
		panic(errRoundRunning)
	}
	if now() <= a.created+entryWindow {
		panic(errNotExpired)
	}
	players := a.lobby
	arenas.Remove(id)
	release(a.stake * int64(len(players)))
	for _, p := range players {
		pay(0, cur, p, a.stake)
	}
	assertSolvent(0, cur)

	chain.Emit("LobbyExpired",
		"arena", id,
		"players", itoa(int64(len(players))),
		"caller", caller.String(),
	)
}

// The four helpers below return a new slice of exactly the length of its
// content, so that nothing else stays in storage. They return nil for an
// empty list.

// withAddr returns list with v added at the end.
func withAddr(list []address, v address) []address {
	out := make([]address, len(list), len(list)+1)
	copy(out, list)
	return append(out, v)
}

// withString returns list with v added at the end.
func withString(list []string, v string) []string {
	out := make([]string, len(list), len(list)+1)
	copy(out, list)
	return append(out, v)
}

// withoutAddr returns list without the element at index at.
func withoutAddr(list []address, at int) []address {
	if len(list) == 1 {
		return nil
	}
	out := make([]address, 0, len(list)-1)
	out = append(out, list[:at]...)
	return append(out, list[at+1:]...)
}

// withoutString returns list without the element at index at.
func withoutString(list []string, at int) []string {
	if len(list) == 1 {
		return nil
	}
	out := make([]string, 0, len(list)-1)
	out = append(out, list[:at]...)
	return append(out, list[at+1:]...)
}

package arena

import (
	"strings"
	"time"

	"gno.land/p/g1t2kg2vtr3fukg43eujkn6x53gfdyakhngt4sfd/gnofly/arena/payout/v0"
)

// Render returns the state of the arenas as markdown, for gnoweb:
//
//	""            the open arenas and the last games played
//	"arena/<id>"  one arena: its rules, lobby and game, or its result
//	"earnings"    the top winners
//
// Everything printed here was validated against a narrow charset when it was
// written (see spec.gno and validate.gno), or is an address the chain gave
// the realm. The only caller-supplied value, the id of an arena page, is
// printed only if it is a valid id. Nothing needs markdown escaping.
func Render(path string) string {
	switch {
	case path == "":
		return renderHome()
	case path == "earnings":
		return renderEarnings()
	case strings.HasPrefix(path, "arena/"):
		id := strings.TrimPrefix(path, "arena/")
		if a := getArena(id); a != nil {
			return renderArena(id, a)
		}
		if r, ok := resultOf(id); ok {
			return renderResult(id, r)
		}
	}
	return "# gnofly arenas\n\nPage not found. Go back to the [overview](" + link("") + ").\n"
}

// link returns the gnoweb URL of a Render path of this realm.
func link(path string) string {
	if path == "" {
		return webPath
	}
	return webPath + ":" + path
}

func renderHome() string {
	var b strings.Builder
	b.WriteString("# gnofly arenas\n\n")
	b.WriteString("Paid games of gnofly, a multiplayer plane game, created by players at [gnofly.xyz/arena](https://gnofly.xyz/arena).\n")
	b.WriteString("A pilot pays the entry price to join, the realm keeps the stakes until the game is over, then credits them by the rule of its mode. Winners claim what they are owed with Claim.\n")
	b.WriteString("The house takes " + percent(feeBps) + " of what a settled game pays out.\n\n")

	b.WriteString("## Open arenas\n\n")
	if arenas.Size() == 0 {
		b.WriteString("No arena has players right now.\n\n")
	} else {
		b.WriteString("| Arena | Mode | Entry | Seats | Lives | Time | Kill target | Pilots |\n|---|---|---|---|---|---|---|---|\n")
		arenas.Iterate("", "", func(id string, v any) bool {
			a := v.(*arena)
			pilots := itoa(int64(len(a.lobby))) + " waiting"
			if a.round != nil {
				pilots = itoa(int64(len(a.round.players))) + " playing"
			}
			b.WriteString("| [" + id[:8] + "](" + link("arena/"+id) + ") | " + a.mode + " | " + gnot(a.stake) +
				" | " + itoa(a.minSeats) + " to " + itoa(a.maxSeats) + " | " + itoa(a.lives) +
				" | " + itoa(a.seconds/60) + " min | " + targetCell(a.killTarget) + " | " + pilots + " |\n")
			return false
		})
		b.WriteByte('\n')
	}

	b.WriteString("## Last games\n\n")
	if len(closed) == 0 {
		b.WriteString("No game is over yet.\n\n")
	} else {
		b.WriteString("| Arena | Mode | Outcome | Pilots | Pot | Fee |\n|---|---|---|---|---|---|\n")
		for i := len(closed) - 1; i >= 0 && i >= len(closed)-10; i-- {
			r, _ := resultOf(closed[i])
			b.WriteString("| [" + closed[i][:8] + "](" + link("arena/"+closed[i]) + ") | " + r.mode + " | " + r.outcome +
				" | " + itoa(r.players) + " | " + gnot(r.pot) + " | " + gnot(r.fee) + " |\n")
		}
		b.WriteByte('\n')
	}

	b.WriteString("| | |\n|---|---|\n")
	b.WriteString("| In escrow | " + gnot(escrowed) + " |\n")
	b.WriteString("| Refund delay | " + itoa(refundDelay) + " s |\n\n")
	b.WriteString("- [Earnings](" + link("earnings") + "): " + itoa(int64(len(winners.addrs))) + " ranked pilots\n")
	return b.String()
}

func renderArena(id string, a *arena) string {
	var b strings.Builder
	b.WriteString("# Arena " + id[:8] + "\n\n")
	b.WriteString("Mode `" + a.mode + "`: " + modeDoc(a.mode) + "\n\n")

	b.WriteString("| | |\n|---|---|\n")
	b.WriteString("| Id | `" + id + "` |\n")
	b.WriteString("| Entry | " + gnot(a.stake) + " |\n")
	b.WriteString("| Seats | " + itoa(a.minSeats) + " to " + itoa(a.maxSeats) + " |\n")
	b.WriteString("| Lives | " + itoa(a.lives) + " |\n")
	b.WriteString("| Game time | " + itoa(a.seconds/60) + " min |\n")
	b.WriteString("| Kill target | " + targetCell(a.killTarget) + " |\n")
	b.WriteString("| Created by | " + a.creator.String() + " |\n")
	b.WriteString("| Takes entries until | " + clock(a.created+entryWindow) + " |\n\n")

	if a.round == nil {
		b.WriteString("## Lobby\n\n")
		b.WriteString("Pilots who paid and wait for the game. They can leave with `Leave` until it starts.\n\n")
		b.WriteString("| Seat | Pilot |\n|---|---|\n")
		for i, player := range a.lobby {
			b.WriteString("| " + itoa(int64(i+1)) + " | " + player.String() + " |\n")
		}
	} else {
		r := a.round
		b.WriteString("## Game\n\n")
		b.WriteString("Started at " + clock(r.startedAt) + " with " + itoa(int64(len(r.players))) +
			" pilots and a pot of " + gnot(a.stake*int64(len(r.players))) + ".\n")
		b.WriteString("If the referee does not settle it, anyone can send the stakes back with `RefundRound` from " +
			clock(r.startedAt+a.seconds+refundDelay) + ".\n\n")
		b.WriteString("| Pilot |\n|---|\n")
		for _, player := range r.players {
			b.WriteString("| " + player.String() + " |\n")
		}
	}
	b.WriteString("\n[Earnings](" + link("earnings") + ") | [Overview](" + link("") + ")\n")
	return b.String()
}

func renderResult(id string, r result) string {
	var b strings.Builder
	b.WriteString("# Arena " + id[:8] + "\n\n")
	b.WriteString("Mode `" + r.mode + "`, " + itoa(r.players) + " pilots, closed at " + clock(r.closedAt) + ": " + r.outcome + ".\n\n")
	b.WriteString("| | |\n|---|---|\n")
	b.WriteString("| Entry | " + gnot(r.stake) + " |\n")
	b.WriteString("| Pot | " + gnot(r.pot) + " |\n")
	b.WriteString("| Fee | " + gnot(r.fee) + " |\n")
	b.WriteString("| Paid | " + paidCell(r) + " |\n")
	b.WriteString("\n[Overview](" + link("") + ")\n")
	return b.String()
}

// targetCell formats a kill target: most arenas end on the clock only.
func targetCell(n int64) string {
	if n == 0 {
		return "none"
	}
	return itoa(n) + " kills"
}

// paidCell lists who was paid what in a round, for a table cell.
func paidCell(r result) string {
	if r.outcome != outcomeSettled {
		return "every stake sent back"
	}
	if len(r.payouts) == 0 {
		return "nobody"
	}
	parts := make([]string, len(r.payouts))
	for i, p := range r.payouts {
		parts[i] = p.Address.String() + " " + gnot(p.Amount)
	}
	return strings.Join(parts, ", ")
}

func renderEarnings() string {
	var b strings.Builder
	b.WriteString("# gnofly arena earnings\n\n")
	b.WriteString("The top " + itoa(topSize) + " pilots by what they won above their own stakes, over every settled round.\n\n")
	if len(winners.addrs) == 0 {
		b.WriteString("Nobody won anything yet.\n")
	} else {
		b.WriteString("| Rank | Pilot | Won | Rounds |\n|---|---|---|---|\n")
		for i, addr := range winners.addrs {
			t := totalsOf(addr)
			b.WriteString("| " + itoa(int64(i+1)) + " | " + addr.String() +
				" | " + gnot(t.won) + " | " + itoa(t.rounds) + " |\n")
		}
	}
	b.WriteString("\n[Back to the overview](" + link("") + ")\n")
	return b.String()
}

// modeDoc is one sentence about the payout rule of a mode.
func modeDoc(mode string) string {
	switch mode {
	case payout.ModeBattleRoyale:
		return "the pot, less the fee, goes to the last pilot flying; when the clock runs out, to the pilot still in with the most kills."
	case payout.ModeDeathmatch:
		return "the pot, less the fee, goes to the top three by kills: 60%, 30% and 10%."
	}
	return "see the payout package."
}

// gnot formats an amount of ugnot in GNOT, without trailing zeros:
// 10000000 gives "10 GNOT", 9500000 gives "9.5 GNOT", 1 gives "0.000001 GNOT".
func gnot(ugnot int64) string {
	whole, frac := ugnot/1000000, ugnot%1000000
	if frac == 0 {
		return itoa(whole) + " GNOT"
	}
	decimals := itoa(1000000 + frac)[1:] // all six of them, zeros included
	end := len(decimals)
	for decimals[end-1] == '0' {
		end--
	}
	return itoa(whole) + "." + decimals[:end] + " GNOT"
}

// percent formats basis points as a percentage, without trailing zeros:
// 500 gives "5%", 250 gives "2.5%", 1 gives "0.01%".
func percent(bps int64) string {
	whole, frac := bps/100, bps%100
	switch {
	case frac == 0:
		return itoa(whole) + "%"
	case frac%10 == 0:
		return itoa(whole) + "." + itoa(frac/10) + "%"
	case frac < 10:
		return itoa(whole) + ".0" + itoa(frac) + "%"
	}
	return itoa(whole) + "." + itoa(frac) + "%"
}

// clock formats a block time in Unix seconds, in UTC.
func clock(unix int64) string {
	return time.Unix(unix, 0).UTC().Format("2006-01-02 15:04:05") + " UTC"
}

package arena

import (
	"strings"

	"gno.land/p/g1t2kg2vtr3fukg43eujkn6x53gfdyakhngt4sfd/gnofly/arena/payout/v0"
)

// result is how a game ended, kept for readers: no payment is ever computed
// from it.
type result struct {
	mode     string
	stake    int64
	outcome  string // settled, cancelled or refunded
	players  int64  // how many played
	pot      int64  // their stakes
	fee      int64
	closedAt int64           // block time, Unix seconds
	payouts  []payout.Payout // who was paid what, in the order of the players
}

const (
	outcomeSettled   = "settled"
	outcomeCancelled = "cancelled"
	outcomeRefunded  = "refunded"
)

// maxResults is how many closed games the realm remembers.
const maxResults = 50

// A result is stored as one string, its fields separated by "|", the payouts
// last as "address:amount" separated by ",":
//
//	mode|stake|outcome|players|pot|fee|closedAt|g1...:19500000,g1...:500000
func (r result) encode() string {
	var b strings.Builder
	b.WriteString(r.mode)
	for _, n := range []string{itoa(r.stake), r.outcome, itoa(r.players), itoa(r.pot), itoa(r.fee), itoa(r.closedAt)} {
		b.WriteByte('|')
		b.WriteString(n)
	}
	b.WriteByte('|')
	b.WriteString(joinPayouts(r.payouts))
	return b.String()
}

func decodeResult(s string) result {
	f := strings.Split(s, "|")
	if len(f) != 8 {
		panic(errCorruptResult)
	}
	num := func(i int) int64 {
		n, ok := digits(f[i])
		if !ok {
			panic(errCorruptResult)
		}
		return n
	}
	r := result{mode: f[0], stake: num(1), outcome: f[2], players: num(3), pot: num(4), fee: num(5), closedAt: num(6)}
	if r.outcome != outcomeSettled && r.outcome != outcomeCancelled && r.outcome != outcomeRefunded {
		panic(errCorruptResult)
	}
	if f[7] == "" {
		return r
	}
	for _, entry := range strings.Split(f[7], ",") {
		colon := indexFrom(entry, 0, ':')
		if colon == 0 || colon == len(entry) {
			panic(errCorruptResult)
		}
		amount, ok := digits(entry[colon+1:])
		if !ok {
			panic(errCorruptResult)
		}
		r.payouts = append(r.payouts, payout.Payout{Address: address(entry[:colon]), Amount: amount})
	}
	return r
}

// record keeps the result of a closed game, and forgets the oldest one past
// maxResults.
func record(id string, r result) {
	results.Set(id, r.encode())
	closed = append(closed, id)
	if len(closed) > maxResults {
		results.Remove(closed[0])
		next := make([]string, len(closed)-1)
		copy(next, closed[1:])
		closed = next
	}
}

// resultOf returns the result of a closed game, if the realm still has it.
func resultOf(id string) (result, bool) {
	v := results.Get(id)
	if v == nil {
		return result{}, false
	}
	return decodeResult(v.(string)), true
}

// indexFrom returns the index of the first c in s at or after i, or len(s).
func indexFrom(s string, i int, c byte) int {
	for i < len(s) && s[i] != c {
		i++
	}
	return i
}

// digits parses a non-negative decimal of at most 18 digits.
func digits(s string) (int64, bool) {
	if len(s) == 0 || len(s) > 18 {
		return 0, false
	}
	n := int64(0)
	for i := 0; i < len(s); i++ {
		c := s[i]
		if c < '0' || c > '9' {
			return 0, false
		}
		n = n*10 + int64(c-'0')
	}
	return n, true
}

package arena

import "gno.land/r/g1t2kg2vtr3fukg43eujkn6x53gfdyakhngt4sfd/gnofly/game/v0"

// The arena realm keeps no roles of its own. Who owns it, who administers
// it, who referees its rounds and where its fee goes are the answers of the
// game realm, asked again at every call: a referee removed there is refused
// here in the same block.

// authority is the set of questions this realm asks about roles.
type authority interface {
	Owner() address
	IsAdmin(addr address) bool
	IsReferee(addr address) bool
	Treasury() address
}

// gameRoles answers with the roles of the game realm.
type gameRoles struct{}

func (gameRoles) Owner() address              { return game.Owner() }
func (gameRoles) IsAdmin(addr address) bool   { return game.IsAdmin(addr) }
func (gameRoles) IsReferee(addr address) bool { return game.IsReferee(addr) }
func (gameRoles) Treasury() address           { return game.Treasury() }

// roles is the authority of this realm: the game realm, always.
//
// It is a variable for one reason. Under `gno test` an imported realm is
// initialized without a deployer, and a test of this package has no way to
// become the owner of the game realm, so the tests put their own answers
// here. Nothing outside the test files assigns it, and there is no setter.
var roles authority = gameRoles{}

// callerOf returns the verified caller of a crossing function. rlm must be
// the cur of the crossing function calling this helper: a stale or forged
// realm value fails IsCurrent, and Previous is only meaningful on a live one.
//
// It takes the realm in second position on purpose, like p/nt/ownable does:
// a function whose first parameter is a realm is a crossing function.
func callerOf(_ int, rlm realm) address {
	if !rlm.IsCurrent() {
		panic(errSpoofedRealm)
	}
	return rlm.Previous().Address()
}

// assertOwner panics unless the caller is the owner of the game realm, and
// returns the caller.
func assertOwner(_ int, rlm realm) address {
	caller := callerOf(0, rlm)
	if caller != roles.Owner() {
		panic(errNotOwner)
	}
	return caller
}

// assertAdmin panics unless the caller is an admin of the game realm, and
// returns the caller.
func assertAdmin(_ int, rlm realm) address {
	caller := callerOf(0, rlm)
	if !roles.IsAdmin(caller) {
		panic(errNotAdmin)
	}
	return caller
}

// assertReferee panics unless the caller is a referee of the game realm, and
// returns the caller.
func assertReferee(_ int, rlm realm) address {
	caller := callerOf(0, rlm)
	if !roles.IsReferee(caller) {
		panic(errNotReferee)
	}
	return caller
}

package arena

import (
	"chain"
	"strings"

	"gno.land/p/g1t2kg2vtr3fukg43eujkn6x53gfdyakhngt4sfd/gnofly/arena/payout/v0"
)

// round is the started game of an arena. Its players are fixed at start, and
// each of them has one stake in it.
type round struct {
	startedAt int64     // block time, Unix seconds
	players   []address // in the order they entered
}

// A game ends in exactly one of three ways: SettleRound, CancelRound or
// RefundRound. Each of them deletes the arena before anything else, so a
// second one finds no arena and aborts.

// StartRound starts the game of an arena with every player of its lobby.
// Referee only. The lobby must hold at least minSeats players; it holds at
// most maxSeats, Enter sees to that. No coin moves: the stakes that were
// owed to the lobby are now owed to the round. It returns how many play.
func StartRound(cur realm, id string) int64 {
	referee := assertReferee(0, cur)
	a := mustArena(id)
	if a.round != nil {
		panic(errRoundRunning)
	}
	if int64(len(a.lobby)) < a.minSeats {
		panic(errTooFewPlayers)
	}
	a.round = &round{startedAt: now(), players: a.lobby}
	a.lobby = nil
	a.tickets = nil

	chain.Emit("RoundStarted",
		"arena", id,
		"players", joinAddrs(a.round.players),
		"startedAt", itoa(a.round.startedAt),
		"referee", referee.String(),
	)
	return int64(len(a.round.players))
}

// SettleRound closes the game of an arena: it applies the rule of its mode
// to what happened, pays the players, and pays the fee to the treasury.
// Referee only.
//
// deaths is "victim:killer" entries separated by ";", in the order they
// happened, "victim:" when nobody shot the victim down, and the empty
// string when nobody died. A player dies at most as often as the arena has
// lives.
//
// The referee is trusted for these facts and for nothing else. The rule
// refuses a victim or a killer who is not a player of the round, and decides
// the amounts. The realm then checks them (see settle) before it pays.
func SettleRound(cur realm, id string, deaths string) {
	referee := assertReferee(0, cur)
	a := runningArena(id)
	list, err := payout.ParseDeaths(deaths)
	if err != nil {
		panic(err)
	}
	rule := payout.Lookup(a.mode)
	if rule == nil {
		panic(errInvalidMode) // cannot happen: parseSpec checked the mode
	}
	// The rule gets a copy of the players: the list the realm pays from is
	// not one a rule can touch.
	players := make([]address, len(a.round.players))
	copy(players, a.round.players)
	g := payout.Game{Stake: a.stake, Lives: a.lives, KillTarget: a.killTarget, FeeBps: feeBps}
	res, err := rule.Settle(g, players, list)
	if err != nil {
		panic(err)
	}
	settle(0, cur, id, a, res, referee)
}

// settle closes the game of an arena with the result of its rule.
//
// It trusts nothing about the result. Before a counter or a coin moves,
// checkResult verifies that only players of the round are paid and that the
// payouts and the fee add up to the pot, to the ugnot.
func settle(_ int, rlm realm, id string, a *arena, res payout.Result, referee address) {
	r := a.round
	pot := a.stake * int64(len(r.players))
	checkResult(pot, r.players, res)

	// The fee goes to the treasury of the game realm as it is now. If that
	// is not an address the realm can pay, the fee goes back to the players
	// instead: shared by the order of the round, the remainder to the first.
	fee := res.Fee
	payouts := res.Payouts
	treasury := roles.Treasury()
	if fee > 0 && (!validAddress(treasury) || treasury == rlm.Address()) {
		payouts = withFeeShared(r.players, payouts, fee)
		fee = 0
	}

	// State first: the arena is gone and its pot is off the books before the
	// first coin leaves.
	arenas.Remove(id)
	release(pot)
	record(id, result{
		mode:     a.mode,
		stake:    a.stake,
		outcome:  outcomeSettled,
		players:  int64(len(r.players)),
		pot:      pot,
		fee:      fee,
		closedAt: now(),
		payouts:  payouts,
	})
	creditRound(a.stake, r.players, payouts)

	// The winnings stay in the realm until each player claims them: a
	// settlement sends no coin to a player, so it cannot fail on one.
	for _, p := range payouts {
		credit(p.Address, id, p.Amount)
	}
	if fee > 0 {
		pay(0, rlm, treasury, fee)
	}
	assertSolvent(0, rlm)

	chain.Emit("RoundSettled",
		"arena", id,
		"players", itoa(int64(len(r.players))),
		"pot", itoa(pot),
		"fee", itoa(fee),
		"payouts", joinPayouts(payouts),
		"treasury", treasury.String(),
		"referee", referee.String(),
	)
}

// withFeeShared returns payouts with fee added, shared between every player
// of the round, in their order: the remainder goes to the first.
func withFeeShared(players []address, payouts []payout.Payout, fee int64) []payout.Payout {
	each := fee / int64(len(players))
	extra := fee - each*int64(len(players))
	out := make([]payout.Payout, 0, len(players))
	for i, p := range players {
		amount := each
		if i == 0 {
			amount += extra
		}
		for _, q := range payouts {
			if q.Address == p {
				amount += q.Amount
			}
		}
		if amount > 0 {
			out = append(out, payout.Payout{Address: p, Amount: amount})
		}
	}
	return out
}

// checkResult panics unless a result can be paid out of a pot: every payout
// goes to a player of the round, a player is paid at most once and never
// zero or less, the fee is not negative, and all of it adds up to the pot
// exactly.
//
// The built-in rules guarantee all of this. The check is here so that the
// realm does not depend on it: whatever a rule returns, the realm never
// sends more than the pot, and never to a stranger.
func checkResult(pot int64, players []address, res payout.Result) {
	// Every amount is bounded by the pot before it is added, so the sum
	// cannot overflow: at most 9 terms of at most 8e9.
	if res.Fee < 0 || res.Fee > pot {
		panic(errNotConserved)
	}
	sum := res.Fee
	paid := make([]bool, len(players))
	for _, p := range res.Payouts {
		seat := indexOfAddr(players, p.Address)
		if seat < 0 || paid[seat] || p.Amount <= 0 {
			panic(errBadSettlement)
		}
		if p.Amount > pot {
			panic(errNotConserved)
		}
		paid[seat] = true
		sum += p.Amount
	}
	if sum != pot {
		panic(errNotConserved)
	}
}

// CancelRound closes the game of an arena without a result: every player
// gets their stake back in full. Referee only.
//
// The game server uses it for a game it cannot referee, for example one it
// finds running when it starts.
func CancelRound(cur realm, id string) {
	referee := assertReferee(0, cur)
	a := runningArena(id)
	refund(0, cur, id, a, outcomeCancelled, "RoundCancelled", referee)
}

// RefundRound closes the game of an arena without a result, like
// CancelRound, and can be called by anyone, once
//
//	startedAt + seconds + RefundDelay()
//
// has passed on the block clock. It is the players' way out when the
// referee never settles: no stake depends on a server staying up.
func RefundRound(cur realm, id string) {
	caller := callerOf(0, cur)
	a := runningArena(id)
	if now() < a.round.startedAt+a.seconds+refundDelay {
		panic(errRefundTooEarly)
	}
	refund(0, cur, id, a, outcomeRefunded, "RoundRefunded", caller)
}

// refund closes the game of an arena and sends every player their stake
// back. No fee is taken.
func refund(_ int, rlm realm, id string, a *arena, outcome, event string, caller address) {
	r := a.round
	pot := a.stake * int64(len(r.players))
	payouts := make([]payout.Payout, len(r.players))
	for i, p := range r.players {
		payouts[i] = payout.Payout{Address: p, Amount: a.stake}
	}

	// State first, as in settle.
	arenas.Remove(id)
	release(pot)
	record(id, result{
		mode:     a.mode,
		stake:    a.stake,
		outcome:  outcome,
		players:  int64(len(r.players)),
		pot:      pot,
		closedAt: now(),
		payouts:  payouts,
	})

	for _, p := range r.players {
		pay(0, rlm, p, a.stake)
	}
	assertSolvent(0, rlm)

	chain.Emit(event,
		"arena", id,
		"players", itoa(int64(len(r.players))),
		"pot", itoa(pot),
		"caller", caller.String(),
	)
}

// runningArena returns an arena whose game is running. It panics for an
// unknown arena and for one whose game has not started.
func runningArena(id string) *arena {
	a := mustArena(id)
	if a.round == nil {
		panic(errNoRound)
	}
	return a
}

// Refund delay bounds, in seconds.
const (
	minRefundDelay = 60
	maxRefundDelay = 86400
)

// SetRefundDelay sets how long after a game's time limit anyone may refund
// it. Admin only.
func SetRefundDelay(cur realm, seconds int64) {
	assertAdmin(0, cur)
	if seconds < minRefundDelay || seconds > maxRefundDelay {
		panic(errInvalidRefundDelay)
	}
	refundDelay = seconds
	version++
	chain.Emit("RefundDelaySet", "seconds", itoa(seconds))
}

// RefundDelay returns the refund delay, in seconds.
func RefundDelay() int64 {
	return refundDelay
}

// joinAddrs writes addresses separated by commas, for an event.
func joinAddrs(list []address) string {
	var b strings.Builder
	for i, a := range list {
		if i > 0 {
			b.WriteByte(',')
		}
		b.WriteString(a.String())
	}
	return b.String()
}

// joinPayouts writes payouts as "address:amount" separated by commas, for
// an event and for the stored results.
func joinPayouts(list []payout.Payout) string {
	var b strings.Builder
	for i, p := range list {
		if i > 0 {
			b.WriteByte(',')
		}
		b.WriteString(p.Address.String())
		b.WriteByte(':')
		b.WriteString(itoa(p.Amount))
	}
	return b.String()
}

package arena

import (
	"crypto/sha256"
	"encoding/hex"
	"strings"

	"gno.land/p/g1t2kg2vtr3fukg43eujkn6x53gfdyakhngt4sfd/gnofly/arena/payout/v0"
)

// An arena is created off chain, by the game server, at a player's request.
// It is described by a spec, a string of fields separated by "|":
//
//	v1|mode|stake|minSeats|maxSeats|lives|seconds|killTarget|creator|created|nonce
//
//	v1|deathmatch|10000000|2|8|3|900|5|g1abc...|1760000000|k3x9
//
// and known by its id, the first 24 hex characters of the SHA-256 of the
// spec. The first player to pay for an arena hands the realm its spec; the
// realm checks it and stores the arena under the id it computes. Nobody can
// change the stake or the rules of an id: a different spec is a different
// id.
//
// created is the server's clock when the arena was proposed. An arena takes
// entries for an hour from then, and its lobby can be closed by anyone after
// that, see ExpireLobby.

// Bounds of a spec, the same as the game server's.
const (
	specVersion = "v1"
	idLen       = 24

	minStake      = 1000000    // ugnot, 1 GNOT
	maxStake      = 1000000000 // ugnot, 1000 GNOT
	minSeconds    = 300        // 5 minutes
	maxSeconds    = 1800       // 30 minutes
	entryWindow   = 3600       // seconds an arena takes entries after it was created
	clockSkew     = 300        // seconds a server clock may run ahead of the chain
	maxNonceLen   = 16
	maxSpecLength = 160

	// feeBps is the house's share of every settled game, for the treasury.
	feeBps = 500
)

// spec is a parsed arena spec.
type spec struct {
	mode       string
	stake      int64
	minSeats   int64
	maxSeats   int64
	lives      int64
	seconds    int64
	killTarget int64
	creator    address
	created    int64
	nonce      string
}

// idOf returns the id of a spec string.
func idOf(s string) string {
	sum := sha256.Sum256([]byte(s))
	return hex.EncodeToString(sum[:])[:idLen]
}

// parseSpec reads and checks a spec string. It panics on anything the realm
// would not play.
func parseSpec(s string) spec {
	if len(s) > maxSpecLength {
		panic(errInvalidSpec)
	}
	f := strings.Split(s, "|")
	if len(f) != 11 || f[0] != specVersion {
		panic(errInvalidSpec)
	}
	num := func(i int) int64 {
		n, ok := digits(f[i])
		if !ok {
			panic(errInvalidSpec)
		}
		return n
	}
	sp := spec{
		mode:       f[1],
		stake:      num(2),
		minSeats:   num(3),
		maxSeats:   num(4),
		lives:      num(5),
		seconds:    num(6),
		killTarget: num(7),
		creator:    address(f[8]),
		created:    num(9),
		nonce:      f[10],
	}
	if payout.Lookup(sp.mode) == nil {
		panic(errInvalidMode)
	}
	if sp.stake < minStake || sp.stake > maxStake {
		panic(errInvalidStake)
	}
	if sp.minSeats < payout.MinPlayers || sp.minSeats > sp.maxSeats || sp.maxSeats > payout.MaxPlayers {
		panic(errInvalidSeats)
	}
	if sp.lives < payout.MinLives || sp.lives > payout.MaxLives {
		panic(errInvalidLives)
	}
	if sp.seconds < minSeconds || sp.seconds > maxSeconds {
		panic(errInvalidSeconds)
	}
	if sp.killTarget > payout.MaxKillTarget {
		panic(errInvalidKillTarget)
	}
	// A battle royale is won by staying in the air: a kill target would end
	// it before that.
	if sp.mode == payout.ModeBattleRoyale && sp.killTarget != 0 {
		panic(errRoyaleTarget)
	}
	if !validAddress(sp.creator) {
		panic(errInvalidAddress)
	}
	if !validNonce(sp.nonce) {
		panic(errInvalidSpec)
	}
	return sp
}

// validNonce reports whether s is 1 to 16 characters of [a-z0-9].
func validNonce(s string) bool {
	if len(s) == 0 || len(s) > maxNonceLen {
		return false
	}
	for i := 0; i < len(s); i++ {
		c := s[i]
		if !(c >= 'a' && c <= 'z') && !(c >= '0' && c <= '9') {
			return false
		}
	}
	return true
}

// validID reports whether s can be an arena id: 24 lowercase hex characters.
func validID(s string) bool {
	if len(s) != idLen {
		return false
	}
	for i := 0; i < len(s); i++ {
		c := s[i]
		if !(c >= '0' && c <= '9') && !(c >= 'a' && c <= 'f') {
			return false
		}
	}
	return true
}

package arena

// The string rules below are what makes the hand-built JSON and the markdown
// of this realm safe: every string that is stored and later printed went
// through one of them, and none of them lets a quote, a backslash, a pipe, a
// bracket or a control character in. They are the rules of the game realm.

const ticketLen = 64 // a SHA-256 in hex

// validTicket reports whether s is 64 lowercase hex characters, the SHA-256
// of the secret a player's client keeps.
func validTicket(s string) bool {
	if len(s) != ticketLen {
		return false
	}
	for i := 0; i < len(s); i++ {
		c := s[i]
		if !(c >= '0' && c <= '9') && !(c >= 'a' && c <= 'f') {
			return false
		}
	}
	return true
}

// validAddress reports whether addr is a valid address in its canonical,
// lowercase form.
//
// Bech32 can also be written in all capitals, and address.IsValid accepts
// that. Bech32 does not allow mixing cases, so looking at the first character
// is enough.
func validAddress(addr address) bool {
	return addr.IsValid() && addr[0] == 'g'
}

// indexOfAddr returns the index of addr in list, -1 when it is not there.
// The lists of this realm hold at most 16 addresses.
func indexOfAddr(list []address, addr address) int {
	for i, a := range list {
		if a == addr {
			return i
		}
	}
	return -1
}
